import clsx from 'clsx';
import { isEmpty } from 'lodash-es';
import { useEffect, useMemo, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { ToggleSetOffRamp } from '~/features/toggle-switches/ui/toggle-set-off-ramp';
import { ThresholdAmountDisplay } from '~/entities/menu/ui/threshold-amount-display';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { setUserRes, useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useGetCstmrWalletListQuery } from '~/entities/user/api/use-get-cstmr-wallet-list-query';
import { useUpdateAutoRampMutation } from '~/entities/user/api/use-update-auto-ramp-mutation';
import { AutoRampUpdateParams } from '~/entities/user/model/types';
import { YesOrNo } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { snackBar } from '~/shared/lib/toast';

type SettingAutoOnOffRampLocationState = {
  aliasNm?: string;
};

const ALL_WALLET_LABEL = '전체 적용';

export const SetOffRampPage = () => {
  const { state } = useLocation();
  const { navigateBack } = useNavigate();
  const { aliasNm: routeAliasNm } = (state as SettingAutoOnOffRampLocationState) ?? {};
  const { data: walletList = [] } = useGetCstmrWalletListQuery();
  const { data: userRes } = useGetUserInfoQuery();
  const { mutateAsync: updateAutoRamp } = useUpdateAutoRampMutation();
  const [thresholdAmount, setThresholdAmount] = useState('');
  const [selectedWalletAliasNm, setSelectedWalletAliasNm] = useState(routeAliasNm ?? '');
  const [dc1AtmcOfframpYn, setDc1AtmcOfframpYn] = useState<string | null>(null);
  const inputRef = useRef<HTMLInputElement | null>(null);

  useSetHeaderTitle(i18n.t('autoOffRamp'));

  const selectedWallet = useMemo(() => {
    const fallbackWallet =
      walletList.find((wallet) => wallet.dfltAliasNm === wallet.aliasNm) ?? walletList[0] ?? ({} as UserWalletResponse);

    if (!selectedWalletAliasNm) {
      return {
        ...fallbackWallet,
        aliasNm: '',
      } as UserWalletResponse;
    }

    return walletList.find((wallet) => wallet.aliasNm === selectedWalletAliasNm) ?? fallbackWallet;
  }, [selectedWalletAliasNm, walletList]);

  useEffect(() => {
    if (!selectedWalletAliasNm) {
      setDc1AtmcOfframpYn(
        walletList.some((wallet) => wallet.dc1AtmcOfframpYn === 'N' || isEmpty(wallet.dc1AtmcOfframpYn)) ? 'N' : 'Y',
      );
      setThresholdAmount('0');
      return;
    }

    if (!selectedWallet) return;
    setDc1AtmcOfframpYn(selectedWallet.dc1AtmcOfframpYn ?? null);
    setThresholdAmount((selectedWallet.threshold ?? 0).toString());
  }, [selectedWallet, selectedWalletAliasNm, walletList]);

  const isDisabled = useMemo(() => {
    if (thresholdAmount === '') return false;
    const amountValue = Number(thresholdAmount);
    return Number.isNaN(amountValue) || amountValue > 1000000000; //한도 10억
  }, [thresholdAmount]);

  if (!selectedWallet) {
    return null;
  }

  const handleClickThresholdInput = () => {
    inputRef.current?.focus({ preventScroll: true });
  };

  const handleChangeThresholdAmount = (value: string) => {
    const numbersOnly = value.replace(/\D/g, '');

    if (!numbersOnly) {
      setThresholdAmount('');
      return;
    }

    setThresholdAmount(numbersOnly.replace(/^0+/, '') || '0');
  };

  const handleChangeOffRamp = (nextValue: string) => {
    setDc1AtmcOfframpYn(nextValue);

    if (nextValue === YesOrNo.아니오) {
      setThresholdAmount('0');
    }
  };

  const onSubmit = async () => {
    if (isDisabled) return;

    const cstmrNo = userRes?.tbCstmrMastr?.cstmrNo;
    if (!cstmrNo) {
      console.error('cstmrNo is not found');
      return;
    }

    const nextOffRampValue = dc1AtmcOfframpYn ?? selectedWallet.dc1AtmcOfframpYn ?? YesOrNo.아니오;
    const hasThresholdAmount = thresholdAmount !== '' && Number(thresholdAmount) > 0;

    if (hasThresholdAmount && nextOffRampValue !== YesOrNo.예) {
      snackBar(i18n.t('text:cannotUseThreshold'), 5000); //5초
      return;
    }

    const shouldResetThreshold = nextOffRampValue === YesOrNo.예 && selectedWallet.dc1AtmcOfframpYn !== YesOrNo.예;
    const nextThreshold =
      nextOffRampValue === YesOrNo.아니오
        ? 0
        : thresholdAmount === ''
          ? shouldResetThreshold
            ? 0
            : undefined
          : Number.parseInt(thresholdAmount, 10);

    const updateAutoRampParams: AutoRampUpdateParams = {
      cstmrNo,
      dc1AtmcOnrampYn: null,
      dc1AtmcOfframpYn: nextOffRampValue,
    };

    if (selectedWallet.aliasNm) {
      updateAutoRampParams.aliasNm = selectedWallet.aliasNm;
    }
    if (nextThreshold !== undefined) {
      updateAutoRampParams.threshold = nextThreshold;
    }

    await updateAutoRamp(updateAutoRampParams);

    setUserRes((prev) => ({
      ...prev,
      tbCstmrMastr: {
        ...prev.tbCstmrMastr,
        dc1AtmcOfframpYn: nextOffRampValue,
        ...(nextThreshold !== undefined ? { threshold: nextThreshold } : {}),
      },
    }));

    navigateBack();
    snackBar(i18n.t('text:setOffRampCompleted'));
  };

  return (
    <div className="wrap bgw">
      <div className="content sub has-btm-btn setting-auto-on-off-page__content">
        <div className="threshold-toggle-wrapper">
          <div className="toggle-area">
            {/* <div className="toggle-box off-ramp-toggle-box">
              <p className="toggle-label">{i18n.t('wallet')}</p>
              <WalletSelect
                aliasNm={selectedWalletAliasNm}
                onChangeAliasNm={setSelectedWalletAliasNm}
                allOptionLabel={ALL_WALLET_LABEL}
                renderTrigger={({ label, onClick }) => (
                  <p className="off-ramp-select-badge off-ramp-select-badge--limited" onClick={onClick}>
                    {label}
                  </p>
                )}
              />
            </div> */}
            <div className="toggle-box off-ramp-toggle-box">
              <p className="toggle-label">{i18n.t('useAutoOffRamp')}</p>
              <ToggleSetOffRamp
                selectedWallet={selectedWallet}
                value={dc1AtmcOfframpYn}
                onChange={handleChangeOffRamp}
              />
            </div>
            <div className="toggle-box off-ramp-toggle-box off-ramp-muted-text">
              <span>{i18n.t('text:useAutoOffRampDesc')}</span>
            </div>
            <div className="off-ramp-toggle-box off-ramp-threshold-box">
              <p className="toggle-label">{i18n.t('enterThreshold')}</p>
              <div className="ipt-form-area pay off-ramp-threshold-input-area">
                <div className="ipt-form pay">
                  <label className="ipt-label pay-label" htmlFor="thresholdAmount">
                    {i18n.t('text:generalEnterAmount')}
                  </label>
                  <div className="ipt-form-box">
                    <input
                      id="thresholdAmount"
                      ref={inputRef}
                      type="number"
                      className="ipt-text"
                      inputMode="numeric"
                      pattern="\d*"
                      value={thresholdAmount}
                      onChange={(event) => handleChangeThresholdAmount(event.target.value)}
                    />
                    <button type="button" className="btn ipt_reset" onClick={() => setThresholdAmount('')}>
                      <span>{i18n.t('deleteAll')}</span>
                    </button>
                  </div>
                </div>
                <ThresholdAmountDisplay
                  trnscAmt={thresholdAmount}
                  error={undefined}
                  handleClickInput={handleClickThresholdInput}
                  allowZero
                  transactionLabel={i18n.t('settingThreshold')}
                />
                <span className="off-ramp-muted-text">{i18n.t('text:thresholdInfo')}</span>
              </div>
            </div>
            {/* <p className="toggle-info whitespace-pre-wrap">{i18n.t('text:useAutoOnRampDesc')}</p> */}
          </div>
        </div>
        <div className="line-box line-2">
          <dl className="info-list">
            <dt>{i18n.t('autoOnOffRampInfo')}</dt>
            <dd>{i18n.t('text:autoOnOffRampExceptionDesc')}</dd>
          </dl>
        </div>
      </div>
      <div className="btm-btn-area">
        <button
          onClick={onSubmit}
          type="button"
          className={clsx('btm-btn app', { disabled: isDisabled })}
          id="charge"
          disabled={isDisabled}
        >
          {i18n.t('confirm')}
        </button>
      </div>
    </div>
  );
};
