import { memo, useCallback, useState } from 'react';
import { TermsInfoBottomSheet } from '~/entities/menu/ui/terms-info-bottom-sheet';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { YesOrNo } from '~/shared/api/dtos/enums';
import { ToggleSwitch } from '~/shared/ui/toggle-switch/toggle-switch';

type Props = {
  selectedWallet: UserWalletResponse;
  value: string | null;
  onChange: (nextValue: string) => void;
};

export const ToggleSetOffRamp = memo(function ToggleTokenAndPayment({ selectedWallet, value, onChange }: Props) {
  const [isTermsOpen, setIsTermsOpen] = useState(false);
  const dc1AtmcOfframpYn = value ?? selectedWallet.dc1AtmcOfframpYn ?? null;

  const handleToggle = useCallback(
    (nextOn: boolean) => {
      if (nextOn && dc1AtmcOfframpYn !== YesOrNo.예) {
        setIsTermsOpen(true);
        return false;
      }

      onChange(nextOn ? YesOrNo.예 : YesOrNo.아니오);
      return true;
    },
    [dc1AtmcOfframpYn, onChange],
  );

  const handleConfirmTerms = useCallback(() => {
    onChange(YesOrNo.예);
    setIsTermsOpen(false);
  }, [onChange]);

  return (
    <>
      <ToggleSwitch on={dc1AtmcOfframpYn === YesOrNo.예} onToggle={handleToggle} />
      <TermsInfoBottomSheet
        isSheetOpen={isTermsOpen}
        onClose={() => setIsTermsOpen(false)}
        onConfirm={handleConfirmTerms}
      />
    </>
  );
});
